Función que lee un archivo .env y retorna solo los nombres de las variables:

export function parseEnvKeys(filePath: string): string[] {
  if (!fs.existsSync(filePath)) return [];
  const content = fs.readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#'))  // ignorar comentarios
    .map(line => line.split('=')[0].trim())           // solo el nombre
    .filter(key => /^[A-Z_][A-Z0-9_]*$/.test(key));  // validar formato
}

IMPORTANTE: nunca capturar el lado derecho del '='.

export type EnvCategory = 'database' | 'auth' | 'api-key' | 'mail' | 'storage' | 'app' | 'unknown';

const CATEGORY_PATTERNS: [RegExp, EnvCategory][] = [
  [/^(DB_|DATABASE_|MYSQL_|POSTGRES_|MONGO_|REDIS_)/i, 'database'],
  [/^(JWT_|AUTH_|SESSION_|NEXTAUTH_|SANCTUM_|OAUTH_)/i, 'auth'],
  [/(API_KEY|_SECRET|_TOKEN|_KEY)$/i, 'api-key'],
  [/^(MAIL_|SMTP_|SENDGRID_|MAILGUN_)/i, 'mail'],
  [/^(S3_|AWS_|GCS_|STORAGE_|CLOUDINARY_)/i, 'storage'],
  [/^(APP_|VITE_|NEXT_PUBLIC_|NUXT_)/i, 'app'],
];

export function classifyEnvKey(key: string): EnvCategory {
  for (const [pattern, category] of CATEGORY_PATTERNS) {
    if (pattern.test(key)) return category;
  }
  return 'unknown';
}
